// tinylm.js — the tiny models from the lessons, rewritten in JavaScript
// so they can run in the browser. The math is the same as the Python code.
// Starting weights are copied from PyTorch (torch.manual_seed(42); torch.randn(...)),
// so the numbers you see on the page match the numbers the Python lessons print.

const TEXT = "the cat sat on the mat. the dog sat on the log.";

// Unique characters, sorted (same order as Python's sorted(set(text)))
const CHARS = Array.from(new Set(TEXT)).sort();
const VOCAB = CHARS.length; // 14
const CHAR_TO_NUMBER = {};
CHARS.forEach((c, i) => { CHAR_TO_NUMBER[c] = i; });

