function copyTable(t) { return t.map(row => row.slice()); }

// Softmax: scores -> probabilities that add up to 1
function softmax(scores) {
  const max = Math.max(...scores);
  const exps = scores.map(s => Math.exp(s - max));
  const total = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / total);
}

// ---------------- Lesson 4: one table, looks at 1 character ----------------
class OneCharModel {
  constructor() {
    this.current = [];
    this.next = [];
    for (let i = 0; i < TEXT.length - 1; i++) {
      this.current.push(CHAR_TO_NUMBER[TEXT[i]]);
      this.next.push(CHAR_TO_NUMBER[TEXT[i + 1]]);
    }
    this.n = this.current.length; // 46 pairs
    // timesUsed[row] = how many pairs start with this character
    // timesCorrect[row][col] = how many times col came right after row
    this.timesUsed = new Array(VOCAB).fill(0);
    this.timesCorrect = Array.from({ length: VOCAB }, () => new Array(VOCAB).fill(0));
    for (let i = 0; i < this.n; i++) {
      this.timesUsed[this.current[i]] += 1;
      this.timesCorrect[this.current[i]][this.next[i]] += 1;
    }
    this.reset();
  }

  reset() {
    this.weights = copyTable(INIT_LESSON4);
    this.grad = null;
    this.step = 0;
    this.lossHistory = [];
  }

  probabilities(row) { return softmax(this.weights[row]); }

  // b) loss = average of -log(probability of the correct next character)
  loss(weights = this.weights) {
    let total = 0;
    for (let i = 0; i < this.n; i++) {
      const p = softmax(weights[this.current[i]]);
      total += -Math.log(p[this.next[i]]);
    }
    return total / this.n;
  }

  // c) gradient for every score: (timesUsed * prob - timesCorrect) / 46
  gradients() {
    const grad = [];
    for (let r = 0; r < VOCAB; r++) {
      const p = this.probabilities(r);
      grad.push(p.map((prob, c) => (this.timesUsed[r] * prob - this.timesCorrect[r][c]) / this.n));
    }
    return grad;
  }

  // One full training step: predict, measure, find directions, move
  trainStep(learningRate = 10) {
    const lossBefore = this.loss();
    const before = copyTable(this.weights);
    this.grad = this.gradients();
    for (let r = 0; r < VOCAB; r++)
      for (let c = 0; c < VOCAB; c++)
        this.weights[r][c] -= learningRate * this.grad[r][c];
    this.lossHistory.push(lossBefore);
    this.step += 1;
    return { lossBefore, before, grad: this.grad, after: this.weights };
  }
}

// ---------------- Lesson 5: three tables, looks at 3 characters ----------------
class ThreeCharModel {
  constructor() {
    this.examples = [];
    for (let i = 0; i < TEXT.length - 3; i++) {
      this.examples.push({
        c1: CHAR_TO_NUMBER[TEXT[i]],
        c2: CHAR_TO_NUMBER[TEXT[i + 1]],
        c3: CHAR_TO_NUMBER[TEXT[i + 2]],
        next: CHAR_TO_NUMBER[TEXT[i + 3]],
      });
    }
    this.reset();
  }

  reset() {
    this.tables = INIT_LESSON5.map(copyTable);
    this.step = 0;
  }

  scores(c1, c2, c3) {
    const [t1, t2, t3] = this.tables;
    return t1[c1].map((v, k) => v + t2[c2][k] + t3[c3][k]);
  }

  trainStep(learningRate = 10) {
    const n = this.examples.length;
    const grads = [0, 1, 2].map(() => Array.from({ length: VOCAB }, () => new Array(VOCAB).fill(0)));
    let total = 0;
    for (const ex of this.examples) {
      const p = softmax(this.scores(ex.c1, ex.c2, ex.c3));
      total += -Math.log(p[ex.next]);
      for (let k = 0; k < VOCAB; k++) {
        const g = (p[k] - (k === ex.next ? 1 : 0)) / n;
        grads[0][ex.c1][k] += g;
        grads[1][ex.c2][k] += g;
        grads[2][ex.c3][k] += g;
      }
    }
    for (let t = 0; t < 3; t++)
      for (let r = 0; r < VOCAB; r++)
        for (let c = 0; c < VOCAB; c++)
          this.tables[t][r][c] -= learningRate * grads[t][r][c];
    this.step += 1;
    return total / n;
  }

  train(steps = 300) { let l = 0; for (let i = 0; i < steps; i++) l = this.trainStep(); return l; }

  // Chances for the next character, given the last 3 characters
  predict(lastThree) {
    const nums = Array.from(lastThree).map(c => CHAR_TO_NUMBER[c]);
    if (nums.length < 3 || nums.some(n => n === undefined)) return null;
    return softmax(this.scores(nums[0], nums[1], nums[2]));
  }
}

// Weighted random pick (like torch.multinomial with num_samples=1)
function pickByChance(chances) {
  let r = Math.random();
  for (let i = 0; i < chances.length; i++) {
    r -= chances[i];
    if (r <= 0) return i;
  }
  return chances.length - 1;
}

// Show a character so spaces are visible
function showChar(c) { return c === " " ? "space" : c; }
